  accounts.each do |label, account|
    start = lines.index { |line| line.match?(/\A#{Regexp.escape(label)}:\s*$/) }
    raise "#{path}: label #{label} not found" unless start

    finish = (start + 1...lines.size).find { |i| lines[i].strip.empty? || lines[i].match?(/\A\S/) } || lines.size
